src='''def transform(grid):
    """Overlay two equal panels, marking their shared background color."""
    h, w = len(grid), len(grid[0])
    split = None
    # Find a uniform interior separator whose removal leaves equal panels.
    for c in range(1, w - 1):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1 and c == w - c - 1:
            split = ("col", c)
            break
    if split is None:
        for r in range(1, h - 1):
            vals = {v for v in grid[r]}
            if len(vals) == 1 and r == h - r - 1:
                split = ("row", r)
                break
    if split is None:
        raise ValueError("No centered uniform separator found")
    axis, idx = split
    if axis == "col":
        left = [row[:idx] for row in grid]
        right = [row[idx + 1:] for row in grid]
    else:
        left = grid[:idx]
        right = grid[idx + 1:]
    colors_left = {v for row in left for v in row}
    colors_right = {v for row in right for v in row}
    shared = colors_left & colors_right
    if len(shared) != 1:
        raise ValueError(f"Expected one shared color, found {shared}")
    color = next(iter(shared))
    out = []
    for a, b in zip(left, right):
        out.append([3 if x == color and y == color else color for x, y in zip(a, b)])
    return out
'''
